    caseId: "102-202-203",
    caseContext:
      "25歳女性。テニスで上腕部の筋肉痛を自覚し、これに効く消炎鎮痛薬の貼付剤を購入する目的で薬局を訪れた。応対した薬剤師はこの女性から以下の4つの情報を聴取した。\n\n・喘息の既往はない。\n・現在、妊娠はしていない。\n・貼付剤で皮膚がかぶれたことはない。\n・以前に日焼け止め剤を使用して過敏症を発症したことがある。",
    field: "物理",

    question:
      "日焼け止め剤には、紫外線吸収剤や紫外線散乱剤が配合されている。ある紫外線吸収剤は共役系を持ち、その遷移エネルギーは 360 kJ・mol⁻¹ であった。この遷移エネルギーに相当する紫外線の波長（nm）として最も近いのはどれか。1つ選べ。\nただし、様々な物理定数は以下の値を用いることとする。\n\nプランク定数 6.6 × 10⁻³⁴ J・s\n光速度 3.0 × 10⁸ m・s⁻¹\nアボガドロ数 6.0 × 10²³ mol⁻¹",

    choices: [
    "240",
    "270",
    "300",
    "330",
    "360"
    ],

    answer: 3,


    explanation:
      "1 molあたりの遷移エネルギー 360 kJ・mol⁻¹ を、1光子あたりに直す。E = 3.6×10⁵ J・mol⁻¹ ÷ 6.0×10²³ mol⁻¹ = 6.0×10⁻¹⁹ J。光のエネルギーは E = hc/λ なので、λ = hc/E = (6.6×10⁻³⁴ × 3.0×10⁸) ÷ (6.0×10⁻¹⁹) = 3.3×10⁻⁷ m = 330 nm。したがって最も近いのは4の330 nm。ほかの選択肢は、この計算値から外れるため不適である。"
