    field: "実務",

    question:
      "22歳女性。体重45 kg。アセトアミノフェンを含有するOTC医薬品を大量に服用し、救急搬送されてきた。服用後約4時間が経過しており、アセトアミノフェンの摂取量から、解毒薬としてアセチルシステイン内用液17.6%の投与が必要と判断された。\n\n投与する用量として、添付文書には「本剤又は本剤を希釈した液を、初回にアセチルシステインとして140 mg/kg、次いでその4時間後から70 mg/kgを4時間毎に17回、計18回経口投与する。」と記載されている。投与されるアセチルシステイン内用液17.6%の総量（mL）として最も近いのはどれか。1つ選べ。",

