    explanation:
      "正答は5の梅毒です。梅毒では、感染初期に陰部などの硬いしこりや潰瘍、鼠径リンパ節の腫れがみられ、その後、全身の発疹（バラ疹など）が現れることがあります。また、2010年代に男女とも届出数が増加しており、図の推移とも一致します。淋菌感染症や性器クラミジア感染症は尿道炎・子宮頸管炎などが中心で、全身の発疹は典型的ではありません。性器ヘルペスは痛みを伴う水疱・潰瘍が特徴ですが、全身発疹や届出数の特徴からは梅毒がより適切です。尖圭コンジローマは外陰部のいぼ状病変が主で、潰瘍や全身発疹とは異なります。"
