      "正答は2、3です。塩化物イオンは、し尿・生活排水・海水などの混入で増加することがあり、汚染の指標の1つとして用いられます。TOCは水中の有機物量の指標で、過マンガン酸カリウム消費量に比べて、亜硝酸イオンなどの還元性無機物の影響を受けにくいとされます。1は、一般細菌の水質基準は100集落/mL以下であり、36集落/mLなので基準内です。4は、トリハロメタンは消毒副生成物であり、濃度が高いからといって色度・濁度が必ず高くなるわけではありません。5は、遊離残留塩素は給水栓で0.1mg/L以上必要で、0.3mg/Lは不足ではなく、通常この理由で飲用不適とはいえません。"
