      "87歳女性。寝たきり。この患者に対して発行された処方箋と残薬を、家族が薬局に持参した。\n\n（持参した残薬の一覧）\nカンデサルタンシレキセチル錠 8 mg　75錠\nシルニジピン錠 20 mg　135錠\nヒドロクロロチアジド錠 25 mg　72錠\nアトルバスタチン錠 10 mg　37錠\n酸化マグネシウム錠 250 mg　232錠\n\n（持参した処方箋の内容）\n（処方1）\nカンデサルタンシレキセチル錠 8 mg　1回1錠（1日1錠）\nシルニジピン錠 20 mg　1回1錠（1日1錠）\nヒドロクロロチアジド錠 25 mg　1回1錠（1日1錠）\nタモキシフェン錠 20 mg　1回1錠（1日1錠）\n1日1回　朝食後　30日分\n\n（処方2）\nアトルバスタチン錠 10 mg　1回1錠（1日1錠）\n1日1回　夕食後　30日分\n\n（処方3）\n酸化マグネシウム錠 250 mg　1回1錠（1日3錠）\n1日3回　朝昼夕食後　30日分",
