      "下記の医薬品を卸売販売業者の担当者が納品に来たので、薬剤師が薬局のカウンターにおいて検収を行った。なお、薬局は、向精神薬営業者に関して別段の申し出はしていないものとする。\n\nセレギリン塩酸塩錠 2.5 mg\nアムロジピン錠 5 mg\nアミオダロン塩酸塩錠 100 mg\nメチルフェニデート塩酸塩錠 10 mg\nフルニトラゼパム錠 2 mg\nペンタゾシン塩酸塩錠 25 mg\nトリメブチンマレイン酸塩 100 mg（要指導医薬品）",
