    "息が切れる、めまいがする、のどが痛い、鼻血がでる、青あざができる。",
    "尿が少なくなる、尿がでない、むくみがある、体がだるい、発疹。",
    "のどがかわく、水分をたくさん摂ってしまう、尿の量が多い、体重が減る。",
