    question:
      "63歳男性。青緑色の吐物を嘔吐し、救急病院に搬送された。医師が家族から状況を聞くと、この男性は認知症であり、買い置きしておいたホウ酸団子をお菓子と間違えて3個食べてしまったという。この男性がホウ酸団子を食べてから5時間以上が経っている。\nホウ酸団子とは、ホウ酸にタマネギ、小麦粉、砂糖、牛乳を加えてつくるゴキブリ駆除剤であり、1個あたり、約3gのホウ酸を含有している。\n担当医師から薬剤師に解毒方法を急いで調べてほしいとの連絡があった。\n\n薬剤師が調べたホウ酸についての情報は以下の通りである。\n【中毒量・致死量】\n中毒量：成人 1〜3g\n経口致死量：成人15〜30g\n\n【体内動態】\nホウ酸は、経口摂取後消化管から1時間以内にほとんどが吸収される。吸収後24時間で約50%が、96時間で90%以上が未変化体として尿中に排泄される。分布容積は小さく、血漿タンパク質にほとんど結合しない。\n\nこの男性に最も有効と考えられる処置法はどれか。1つ選べ。",

    choices: [
    "胃洗浄",
    "活性炭の投与",
    "プラリドキシムヨウ化物（PAM）の投与",
    "クエン酸マグネシウムの投与",
    "血液透析"
    ],

    answer: 4,


    explanation:
      "ホウ酸団子3個で約9gのホウ酸を摂取しており、中毒量を大きく超えています。ホウ酸は摂取後1時間以内にほとんど吸収され、今回は5時間以上経過しているため、消化管内から除去する処置の効果は期待しにくいです。一方、ホウ酸は分布容積が小さく、血漿タンパク結合がほとんどなく、未変化体で尿中排泄されるため、血液透析で除去されやすいと考えられます。したがって最も有効なのは5です。1の胃洗浄は摂取直後なら検討されますが、時間が経過しています。2の活性炭はホウ酸には効果が乏しいとされます。3のPAMは有機リン中毒の解毒薬です。4のクエン酸マグネシウムは下剤であり、吸収後のホウ酸除去には不十分です。"
